import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/inventory.db'
ADMIN_SECRET = os.environ.get('ADMIN_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS products (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL,
        sku TEXT UNIQUE,
        quantity INTEGER DEFAULT 0,
        warehouse TEXT DEFAULT 'main'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        details TEXT,
        ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    )''')
    db.execute("INSERT OR IGNORE INTO products (id, name, sku, quantity, warehouse) VALUES (1, 'Widget A', 'WA-001', 150, 'main')")
    db.execute("INSERT OR IGNORE INTO products (id, name, sku, quantity, warehouse) VALUES (2, 'Widget B', 'WB-002', 75, 'secondary')")
    db.commit()
    db.close()

@app.before_request
def check_auth():
    # Internal endpoints require admin token
    if request.path.startswith('/admin'):
        token = request.headers.get('X-Admin-Token', '')
        if not hashlib.sha256(token.encode()).hexdigest() == hashlib.sha256(ADMIN_SECRET.encode()).hexdigest():
            return jsonify({'error': 'unauthorized'}), 401

@app.route('/api/products/search')
def search_products():
    """Search products by warehouse location and optional name filter.
    Used by the warehouse management UI for inventory lookups."""
    warehouse = request.args.get('warehouse', 'main')
    name_filter = request.args.get('name', '')

    db = get_db()
    # Build query with warehouse filter
    # Note: warehouse is validated against known values in the load balancer routing
    query = f"SELECT id, name, sku, quantity, warehouse FROM products WHERE warehouse = '{warehouse}'"

    if name_filter:
        # Additional filter - append to query
        query += f" AND name LIKE '%{name_filter}%'"

    try:
        results = db.execute(query).fetchall()
        return jsonify([dict(row) for row in results])
    except Exception as e:
        # Log error for debugging
        app.logger.error(f"Query failed: {query} - Error: {e}")
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>')
def get_product(product_id):
    db = get_db()
    product = db.execute('SELECT * FROM products WHERE id = ?', (product_id,)).fetchone()
    if product:
        return jsonify(dict(product))
    return jsonify({'error': 'not found'}), 404

@app.route('/admin/restock', methods=['POST'])
def restock():
    data = request.get_json()
    sku = data.get('sku')
    qty = data.get('quantity', 0)
    if not sku or not isinstance(qty, int):
        return jsonify({'error': 'invalid input'}), 400
    db = get_db()
    db.execute('UPDATE products SET quantity = quantity + ? WHERE sku = ?', (qty, sku))
    db.commit()
    db.execute('INSERT INTO audit_log (action, details) VALUES (?, ?)',
               ('restock', f'{sku}: +{qty}'))
    db.commit()
    return jsonify({'status': 'ok'})

@app.route('/health')
def health():
    return jsonify({'status': 'healthy', 'db': os.path.exists(DATABASE)})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
